L46_1.m_Talk_THA = L47_1
L47_1 = "Nghe c\195\179 v\225\186\187 n\225\187\177c c\198\176\225\187\157i, nh\198\176ng n\196\131m n\195\160y qua n\196\131m kh\195\161c, s\225\187\177 t\225\187\169c gi\225\186\173n m\195\160 t\195\180i d\195\160nh cho h\225\187\141 v\195\172 \196\145\195\163 b\225\186\175t c\195\179c t\195\180i bi\225\186\191n m\225\186\165t d\225\186\167n v\195\160 m\225\187\153t \196\145\225\187\153ng l\225\187\177c c\225\186\161nh tranh k\225\187\179 l\225\186\161 b\225\186\175t \196\145\225\186\167u tr\195\160n ng\225\186\173p trong t\195\162m tr\195\173 t\195\180i."
